```yaml
name: Auto‑triage new issues

on:
  issues:
    types: [opened]

permissions:
  issues: write

jobs:
  triage:
    runs-on: ubuntu-latest
    steps:
      - name: Auto‑triage issue
        uses: actions/github-script@v6
        with:
          script: |
            const { owner, repo } = context.repo;
            const issue = context.payload.issue;
            const number = issue.number;
            const title = issue.title || '';
            const body = issue.body || '';
            const text = `${title}\n${body}`.toLowerCase();

            const bugKeywords = ['bug', 'error', 'crash', 'broken', 'fix', 'fail', 'wrong', 'regression'];
            const featureKeywords = ['feat', 'feature', 'enhancement', 'add', 'implement', 'request', 'improve'];
            const highKeywords = ['critical', 'urgent', 'blocker', 'blocking', 'severe', 'p0', 'p1'];
            const lowKeywords = ['minor', 'trivial', 'nice to have', 'low priority', 'p3', 'p4'];

            const containsKeyword = (keywords) => {
              return keywords.some(k => new RegExp(`\\b${k}\\b`, 'i').test(text));
            };

            // Determine type
            let typeLabel = 'feature-request';
            if (containsKeyword(bugKeywords)) {
              typeLabel = 'bug';
            } else if (containsKeyword(featureKeywords)) {
              typeLabel = 'feature-request';
            }

            // Determine priority
            let priority = 'medium';
            if (containsKeyword(highKeywords)) {
              priority = 'high';
            } else if (containsKeyword(lowKeywords)) {
              priority = 'low';
            }

            const priorityLabel = `priority: ${priority}`;
            const labelsToAdd = [typeLabel, priorityLabel];

            // Label colors
            const labelColors = {
              'bug': 'd73a4a',
              'feature-request': 'a2eeef',
              'priority: high': 'ff0000',
              'priority: medium': 'ffcc00',
              'priority: low': '00ff00'
            };

            // Ensure labels exist
            for (const label of labelsToAdd) {
              try {
                await octokit.issues.getLabel({ owner, repo, name: label });
              } catch (error) {
                if (error.status === 404) {
                  await octokit.issues.createLabel({
                    owner,
                    repo,
                    name: label,
                    color: labelColors[label] || 'ffffff'
                  });
                } else {
                  throw error;
                }
              }
            }

            // Add labels to the issue
            await octokit.issues.addLabels({
              owner,
              repo,
              issue_number: number,
              labels: labelsToAdd
            });
```

